import * as O from './orig.mjs';
import * as N from './new.mjs';
import assert from 'node:assert/strict';
const names = ['choi','kim','lee','park','jung'];
const rnd = (a,b) => a + Math.floor(Math.random()*(b-a+1));
let n=0;
// examples
const ex = [
  () => [ ['doubled', [{choi:48,kim:81,park:98}]], ['doubled', [{jung:-2,lee:1}]],
    ['byNameKey', [[{id:6,name:'choi',age:21},{id:5,name:'lee',age:45},{id:9,name:'park',age:29},{id:6,name:'choi',age:44},{id:8,name:'kim',age:36},{id:0,name:'kim',age:38},{id:1,name:'choi',age:54},{id:2,name:'park',age:36}]]],
    ['byNameKey', [[{id:8,name:'kim',age:36},{id:8,name:'choi',age:50},{id:5,name:'kim',age:28},{id:7,name:'jung',age:41},{id:1,name:'choi',age:19},{id:6,name:'park',age:20},{id:0,name:'choi',age:26},{id:7,name:'kim',age:46}]]],
    ['dedupeSorted', [[2,5,7,14,20]]], ['dedupeSorted', [[5,7,9,11,12,13,15,17,19]]] ]
];
for (const [fn, args] of ex()) { assert.deepStrictEqual(N[fn](...args), O[fn](...args)); n++; }
// random within ranges
for (let t=0;t<5000;t++) {
  const obj={}; const k=rnd(0,5); for(let i=0;i<k;i++) obj[names[rnd(0,4)]] = rnd(-5,99);
  assert.deepStrictEqual(N.doubled(obj), O.doubled(obj)); n++;
  const rows=[]; const m=rnd(0,12); for(let i=0;i<m;i++) rows.push({id:rnd(0,9),name:names[rnd(0,4)],age:rnd(18,60)});
  assert.deepStrictEqual(N.byNameKey(rows), O.byNameKey(rows)); n++;
  const vals=[]; const q=rnd(0,20); let cur=rnd(-5,20); for(let i=0;i<q;i++){ vals.push(cur); cur+=rnd(0,3); }
  // keep within -5..20 by clamping sorted array
  const v2 = vals.map(x=>Math.min(20,Math.max(-5,x))).sort((a,b)=>a-b);
  assert.deepStrictEqual(N.dedupeSorted(v2), O.dedupeSorted(v2)); n++;
}
// edge: empty
assert.deepStrictEqual(N.doubled({}), O.doubled({})); assert.deepStrictEqual(N.byNameKey([]), O.byNameKey([])); assert.deepStrictEqual(N.dedupeSorted([]), O.dedupeSorted([])); n+=3;
console.log('all equal, cases:', n);
EOF
node "$S/compare.mjs"; echo "exit $?"

